<?php
declare(strict_types=1);
namespace app\common\service\app\aigc_copywriting;
use think\facade\Db;
final class CopywritingSeeder {
 public static function catalog():array{return json_decode(file_get_contents(dirname(__DIR__,4).'/apps/aigc_copywriting/data/builtin-tools.json'),true,512,JSON_THROW_ON_ERROR);}
 public static function ensureTenant(int $tenantId):array {if($tenantId<=0)return ['inserted'=>0,'skipped'=>0,'seed_version'=>'1.0.0'];return Db::transaction(function()use($tenantId){$inserted=0;$skipped=0;$categories=[];Db::name('tenant')->where('id',$tenantId)->lock(true)->find();self::upgradePresentation($tenantId);if(CopywritingStore::table('tool')->where('tenant_id',$tenantId)->whereNotNull('builtin_code')->count()>=12&&CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'page_code'=>'home'])->find())return ['inserted'=>0,'skipped'=>12,'seed_version'=>'1.0.0'];foreach(['风险优化','创作输出','平台图文','内容提取']as $i=>$name){$code=['risk','creation','platform','extraction'][$i];$q=CopywritingStore::table('category')->where(['tenant_id'=>$tenantId,'code'=>$code]);$row=$q->find();$categories[$name]=$row['id']??CopywritingStore::insert('category',['tenant_id'=>$tenantId,'code'=>$code,'name'=>$name,'sort'=>100-$i]);}foreach(self::catalog()as $tool){if(CopywritingStore::table('tool')->where(['tenant_id'=>$tenantId,'builtin_code'=>$tool['code']])->find()){$skipped++;continue;}CopywritingDocument::assertValid($tool['document']);$id=CopywritingStore::insert('tool',['tenant_id'=>$tenantId,'tool_code'=>$tool['code'],'builtin_code'=>$tool['code'],'name'=>$tool['name'],'description'=>$tool['description'],'icon'=>$tool['icon'],'category_id'=>$categories[$tool['category']],'sort'=>100-$inserted]);$page=CopywritingStore::insert('page',['tenant_id'=>$tenantId,'page_code'=>$tool['code'],'kind'=>'tool','tool_id'=>$id,'draft_json'=>CopywritingStore::json($tool['document'])]);$v=CopywritingStore::insert('version',['tenant_id'=>$tenantId,'page_id'=>$page,'version_no'=>1,'document_json'=>CopywritingStore::json($tool['document']),'schema_hash'=>hash('sha256',CopywritingStore::json($tool['document'])),'publish_targets'=>'pc,h5,mp-weixin']);CopywritingStore::table('page')->where('id',$page)->update(['published_version_id'=>$v]);$inserted++;}if(!CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'page_code'=>'home'])->find()){$home=self::homeDocument();$page=CopywritingStore::insert('page',['tenant_id'=>$tenantId,'page_code'=>'home','kind'=>'home','draft_json'=>CopywritingStore::json($home)]);$v=CopywritingStore::insert('version',['tenant_id'=>$tenantId,'page_id'=>$page,'version_no'=>1,'document_json'=>CopywritingStore::json($home),'schema_hash'=>hash('sha256',CopywritingStore::json($home)),'publish_targets'=>'pc,h5,mp-weixin']);CopywritingStore::table('page')->where('id',$page)->update(['published_version_id'=>$v]);}return compact('inserted','skipped')+['seed_version'=>'1.0.0'];});}

 public static function homeDocument(): array {return CopywritingDocument::normalize(json_decode(file_get_contents(dirname(__DIR__,4).'/apps/aigc_copywriting/data/home-v2.json'),true,512,JSON_THROW_ON_ERROR));}
 /** Upgrade only untouched defaults; never overwrite a tenant draft or a custom icon. */
 private static function upgradePresentation(int $tenantId): void {
  foreach(self::catalog() as $tool){CopywritingStore::table('tool')->where(['tenant_id'=>$tenantId,'builtin_code'=>$tool['code']])->where(function($q){$q->where('icon','resource/image/common/menu_generator.png')->whereOr(function($empty){$empty->where('icon','')->where('is_customized',0);});})->update(['icon'=>$tool['icon']]);}
  $page=CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'page_code'=>'home'])->find();if(!$page||!$page['published_version_id'])return;
  $legacy=CopywritingDocument::normalize(json_decode(file_get_contents(dirname(__DIR__,4).'/apps/aigc_copywriting/data/home-v1.json'),true,512,JSON_THROW_ON_ERROR));
  $version=CopywritingStore::owned('version',$tenantId,(int)$page['published_version_id']);
  if(CopywritingStore::decode($page['draft_json'])!=$legacy||CopywritingStore::decode($version['document_json'])!=$legacy)return;
  $json=CopywritingStore::json(self::homeDocument());$number=(int)CopywritingStore::table('version')->where('page_id',$page['id'])->max('version_no')+1;
  $id=CopywritingStore::insert('version',['tenant_id'=>$tenantId,'page_id'=>$page['id'],'version_no'=>$number,'document_json'=>$json,'schema_hash'=>hash('sha256',$json),'publish_targets'=>$version['publish_targets']]);
  CopywritingStore::table('page')->where('id',$page['id'])->update(['draft_json'=>$json,'draft_revision'=>(int)$page['draft_revision']+1,'published_version_id'=>$id,'update_time'=>time()]);
 }
}
